CREATE TABLE "CuentasPorPagar" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_CuentasPorPagar" PRIMARY KEY,
    "ProveedorId" integer NOT NULL,
    "OrdenAbastecimientoId" integer,
    "Serie" character varying(10) NOT NULL,
    "NumeroDocumento" character varying(40) NOT NULL,
    "FechaDocumento" date NOT NULL,
    "FechaVencimiento" date NOT NULL,
    "Moneda" character(3) NOT NULL,
    "BaseImponible" numeric(18,2) NOT NULL,
    "ImporteImpuesto" numeric(18,2) NOT NULL,
    "Total" numeric(18,2) NOT NULL,
    "FechaRegistro" timestamp with time zone NOT NULL DEFAULT now(),
    "FechaAnulacion" timestamp with time zone,
    "MotivoAnulacion" character varying(300),
    CONSTRAINT "FK_CuentasPorPagar_Proveedor" FOREIGN KEY ("ProveedorId") REFERENCES "Proveedores" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_CuentasPorPagar_OrdenAbastecimiento" FOREIGN KEY ("OrdenAbastecimientoId") REFERENCES "OrdenesAbastecimiento" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_CuentasPorPagar_Clave" CHECK (
        "Serie" <> '' AND "Serie" !~ '[[:space:]]' AND "Serie" = upper("Serie" COLLATE "C")
        AND "NumeroDocumento" <> '' AND "NumeroDocumento" !~ '[[:space:]]'
        AND "NumeroDocumento" = upper("NumeroDocumento" COLLATE "C")),
    CONSTRAINT "CK_CuentasPorPagar_Moneda" CHECK ("Moneda" IN ('PEN', 'USD')),
    CONSTRAINT "CK_CuentasPorPagar_Importes" CHECK (
        "BaseImponible" >= 0 AND "BaseImponible" <> 'NaN'::numeric
        AND "ImporteImpuesto" >= 0 AND "ImporteImpuesto" <> 'NaN'::numeric
        AND "Total" > 0 AND "Total" <> 'NaN'::numeric AND "Total" = "BaseImponible" + "ImporteImpuesto"),
    CONSTRAINT "CK_CuentasPorPagar_Anulacion" CHECK (
        ("FechaAnulacion" IS NULL AND "MotivoAnulacion" IS NULL)
        OR ("FechaAnulacion" IS NOT NULL AND "MotivoAnulacion" IS NOT NULL
            AND char_length(btrim("MotivoAnulacion")) BETWEEN 3 AND 300))
);

CREATE UNIQUE INDEX "IX_CuentasPorPagar_ProveedorSerieNumero" ON "CuentasPorPagar" ("ProveedorId", "Serie", "NumeroDocumento");
CREATE INDEX "IX_CuentasPorPagar_OrdenAbastecimientoId" ON "CuentasPorPagar" ("OrdenAbastecimientoId");
CREATE INDEX "IX_CuentasPorPagar_FechaVencimiento" ON "CuentasPorPagar" ("FechaVencimiento");
CREATE INDEX "IX_CuentasPorPagar_MonedaFechaRegistroId" ON "CuentasPorPagar" ("Moneda", "FechaRegistro" DESC, "Id" DESC);

CREATE TABLE "AplicacionesPago" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_AplicacionesPago" PRIMARY KEY,
    "CuentaPorPagarId" integer NOT NULL,
    "Importe" numeric(18,2) NOT NULL,
    "FechaPago" date NOT NULL,
    "FechaRegistro" timestamp with time zone NOT NULL DEFAULT now(),
    "FechaReversion" timestamp with time zone,
    "MotivoReversion" character varying(300),
    CONSTRAINT "FK_AplicacionesPago_CuentaPorPagar" FOREIGN KEY ("CuentaPorPagarId") REFERENCES "CuentasPorPagar" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_AplicacionesPago_Importe" CHECK ("Importe" > 0 AND "Importe" <> 'NaN'::numeric),
    CONSTRAINT "CK_AplicacionesPago_Reversion" CHECK (
        ("FechaReversion" IS NULL AND "MotivoReversion" IS NULL)
        OR ("FechaReversion" IS NOT NULL AND "MotivoReversion" IS NOT NULL
            AND char_length(btrim("MotivoReversion")) BETWEEN 3 AND 300))
);

CREATE INDEX "IX_AplicacionesPago_CuentaFechaId" ON "AplicacionesPago" ("CuentaPorPagarId", "FechaPago" DESC, "Id" DESC);
